# Master syllabus for the DNA computing audio course.
# Edit this file, then run build_hub.py. Lesson briefs live in briefs_data.py.
from urllib.parse import quote_plus

NLM_PREAMBLE = ("Audience: a chemical engineer starting a PhD in DNA computing; strong in kinetics, "
                "thermodynamics and transport, new to computer science and machine learning. "
                "Explain each computing or machine-learning term in plain words the first time it appears.")

APPLE_MLG = "https://podcasts.apple.com/podcast/id1204521130"
APPLE_MOLPIGS = "https://podcasts.apple.com/gb/podcast/the-molpigs-podcast/id1555947480"

def web(label, url, check="opened"):   # check: opened | indexed | record | pattern | search
    return {"label": label, "url": url, "check": check}
def pm(pmid):   return web("PubMed record", f"https://pubmed.ncbi.nlm.nih.gov/{pmid}/", "record")
def pmc(pid):   return web("Free full text (PMC)", f"https://pmc.ncbi.nlm.nih.gov/articles/{pid}/", "record")
def doi(d):     return web("Publisher page (DOI)", f"https://doi.org/{d}", "record")
def scholar(q): return web("Find the paper (search)", "https://scholar.google.com/scholar?q=" + quote_plus(q), "search")
def yt(q):      return web("Find on YouTube (search)", "https://www.youtube.com/results?search_query=" + quote_plus(q), "search")
def mlg(n):     return [web("Machine Learning Guide in Apple Podcasts", APPLE_MLG, "indexed"),
                        web("Episode page with player", f"https://ocdevel.com/mlg/{n}", "pattern")]

def lesson(id, title, mins, sum, track="core", pairs=None):
    return {"id": id, "kind": "lesson", "track": track, "title": title, "mins": mins, "sum": sum, "pairs": pairs}
def ext(id, kind, title, source, mins, why, links, track="core", pairs=None, pick=False, note=None):
    return {"id": id, "kind": kind, "track": track, "title": title, "source": source, "mins": mins,
            "why": why, "links": links, "pairs": pairs, "pick": pick, "note": note}
def paper(id, cite, title, why, focus, links, length="Default", track="core", pairs=None, pick=False, note=None):
    return {"id": id, "kind": "paper", "track": track, "title": title, "source": cite,
            "mins": 30 if length == "Longer" else 18, "why": why, "links": links, "pairs": pairs, "pick": pick,
            "note": note, "nlm": {"format": "Deep Dive", "length": length, "focus": focus}}
def lab(id, title, mins, sum, track="core"):
    return {"id": id, "kind": "lab", "track": track, "title": title, "mins": mins, "sum": sum}

YT_NOTE = "No YouTube Premium: keep the screen on, or add the YouTube link to NotebookLM as a source and generate a Deep Dive."
